#include <iostream>
#include <array>

constexpr int GRID_SIZE = 9;
using Grid = std::array<std::array<int, GRID_SIZE>, GRID_SIZE>;

bool isValidCell(int row, int col, const Grid& grid) {
    int val = grid[row][col];
    if (val < 1 || val > 9) return false;

    // Check row uniqueness
    for (int c = 0; c < GRID_SIZE; ++c) {
        if (c != col && grid[row][c] == val) return false;
    }

    // Check column uniqueness
    for (int r = 0; r < GRID_SIZE; ++r) {
        if (r != row && grid[r][col] == val) return false;
    }

    // Check 3x3 box uniqueness
    int boxStartRow = (row / 3) * 3;
    int boxStartCol = (col / 3) * 3;
    for (int r = boxStartRow; r < boxStartRow + 3; ++r) {
        for (int c = boxStartCol; c < boxStartCol + 3; ++c) {
            if ((r != row || c != col) && grid[r][c] == val) return false;
        }
    }

    return true;
}

bool isValidGrid(const Grid& grid) {
    for (int r = 0; r < GRID_SIZE; ++r) {
        for (int c = 0; c < GRID_SIZE; ++c) {
            if (!isValidCell(r, c, grid)) return false;
        }
    }
    return true;
}

int main() {
    Grid grid{};
    for (int r = 0; r < GRID_SIZE; ++r) {
        for (int c = 0; c < GRID_SIZE; ++c) {
            if (!(std::cin >> grid[r][c])) {
                return 0;
            }
        }
    }

    if (isValidGrid(grid)) {
        std::cout << "Valid solution\n";
    } else {
        std::cout << "Invalid solution\n";
    }

    return 0;
}

#include <iostream>
#include <iomanip>

int main() {
    const int NUMBER_OF_DAYS = 2;
    const int NUMBER_OF_HOURS = 3;
    // data[day][hour][0: temp, 1: humidity]
    double data[NUMBER_OF_DAYS][NUMBER_OF_HOURS][2] = {};

    // Simulated input: records can be out of order
    // format: day hour temp humidity (day 1-indexed, hour 1-indexed)
    int totalRecords = NUMBER_OF_DAYS * NUMBER_OF_HOURS;
    for (int k = 0; k < totalRecords; ++k) {
        int day, hour;
        double temp, humidity;
        if (std::cin >> day >> hour >> temp >> humidity) {
            data[day - 1][hour - 1][0] = temp;
            data[day - 1][hour - 1][1] = humidity;
        }
    }

    std::cout << std::fixed << std::setprecision(2);
    for (int i = 0; i < NUMBER_OF_DAYS; ++i) {
        double dailyTempTotal = 0.0;
        double dailyHumidityTotal = 0.0;
        for (int j = 0; j < NUMBER_OF_HOURS; ++j) {
            dailyTempTotal += data[i][j][0];
            dailyHumidityTotal += data[i][j][1];
        }
        std::cout << "Day " << i << " average temp: " 
                  << (dailyTempTotal / NUMBER_OF_HOURS)
                  << ", humidity: " 
                  << (dailyHumidityTotal / NUMBER_OF_HOURS) << "\n";
    }

    return 0;
}
